window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d2284518ead111ad"]={"versions": [{"id": "FIG-d2284518ead111ad", "releases": ["R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für die Validierung diagnostischer Dienste (<code>DiagnosticServiceValidationInterface</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine vertikale Vererbungshierarchie aus drei Klassen bzw. Metamodell-Elementen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code> (oberste Klasse, kursiv gesetzt als abstrakte Klasse) mit den rechtsbündig gesetzten Stereotypen/Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>DiagnosticPortInterface</code> (mittlere Klasse, kursiv gesetzt als abstrakte Klasse), spezialisiert <code>PortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierung).\n</li><li><code>DiagnosticServiceValidationInterface</code> (untere, konkrete Klasse), spezialisiert <code>DiagnosticPortInterface</code> über eine Generalisierungsbeziehung.\n</li></ul>\n<p class=\"fig-p\">Die Klassenblöcke enthalten keine dargestellten Attribute oder Operationen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ, dass <code>DiagnosticServiceValidationInterface</code> eine Spezialisierung von <code>DiagnosticPortInterface</code> und darüber von <code>PortInterface</code> darstellt. Implementierungen und Manifest-Generatoren müssen <code>DiagnosticServiceValidationInterface</code> als spezialisiertes Port-Interface behandeln, welches die Eigenschaften von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> erbt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-30f45b2cab2aaff4", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für die Validierung diagnostischer Dienste (<code>DiagnosticServiceValidationInterface</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine vertikale Vererbungshierarchie aus drei Klassen bzw. Metamodell-Elementen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code> (oberste Klasse, kursiv gesetzt als abstrakte Klasse) mit den rechtsbündig gesetzten Stereotypen/Tags <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>DiagnosticPortInterface</code> (mittlere Klasse, kursiv gesetzt als abstrakte Klasse), spezialisiert <code>PortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierung).\n</li><li><code>DiagnosticServiceValidationInterface</code> (untere, konkrete Klasse), spezialisiert <code>DiagnosticPortInterface</code> über eine Generalisierungsbeziehung.\n</li></ul>\n<p class=\"fig-p\">Die Klassenblöcke enthalten keine dargestellten Attribute oder Operationen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert normativ, dass <code>DiagnosticServiceValidationInterface</code> eine Spezialisierung von <code>DiagnosticPortInterface</code> und darüber von <code>PortInterface</code> darstellt. Implementierungen und Manifest-Generatoren müssen <code>DiagnosticServiceValidationInterface</code> als spezialisiertes Port-Interface behandeln, welches die Eigenschaften von <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code> erbt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-00e7b49fe6fe9e78", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm stellt die Generalisierungsbeziehung von <code>DiagnosticServiceValidationInterface</code> zu <code>DiagnosticPortInterface</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Klassenblöcke:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticPortInterface</code> (oberer Klassenblock, Klassenname kursiv) mit dem rechtsbündig gesetzten kursiven Stereotyp bzw. Kontextvermerk <code>PortInterface</code>.\n</li><li><code>DiagnosticServiceValidationInterface</code> (unterer Klassenblock), spezialisiert <code>DiagnosticPortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierungsbeziehung).\n</li></ul>\n<p class=\"fig-p\">Attribute oder Methoden sind in den Klassenblöcken nicht aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ fest, dass <code>DiagnosticServiceValidationInterface</code> von <code>DiagnosticPortInterface</code> (im Kontext von <code>PortInterface</code>) abgeleitet ist. Manifest-Modellierer und Generatoren leiten die Validierungsschnittstelle für Diagnosedienste aus der abstrakten Diagnose-Port-Schnittstelle ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-74d3e8457a658547", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm stellt die Generalisierungsbeziehung von <code>DiagnosticServiceValidationInterface</code> zu <code>DiagnosticPortInterface</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Klassenblöcke:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticPortInterface</code> (oberer Klassenblock, Klassenname kursiv) mit dem rechtsbündig gesetzten kursiven Stereotyp bzw. Kontextvermerk <code>PortInterface</code>.\n</li><li><code>DiagnosticServiceValidationInterface</code> (unterer Klassenblock), spezialisiert <code>DiagnosticPortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierungsbeziehung).\n</li></ul>\n<p class=\"fig-p\">Attribute oder Methoden sind in den Klassenblöcken nicht aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ fest, dass <code>DiagnosticServiceValidationInterface</code> von <code>DiagnosticPortInterface</code> (im Kontext von <code>PortInterface</code>) abgeleitet ist. Manifest-Modellierer und Generatoren leiten die Validierungsschnittstelle für Diagnosedienste aus der abstrakten Diagnose-Port-Schnittstelle ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6bc4ed2660cf340b", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm stellt die Generalisierungsbeziehung von <code>DiagnosticServiceValidationInterface</code> zu <code>DiagnosticPortInterface</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Klassenblöcke:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticPortInterface</code> (oberer Klassenblock, Klassenname kursiv) mit dem rechtsbündig gesetzten kursiven Stereotyp bzw. Kontextvermerk <code>PortInterface</code>.\n</li><li><code>DiagnosticServiceValidationInterface</code> (unterer Klassenblock), spezialisiert <code>DiagnosticPortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierungsbeziehung).\n</li></ul>\n<p class=\"fig-p\">Attribute oder Methoden sind in den Klassenblöcken nicht aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ fest, dass <code>DiagnosticServiceValidationInterface</code> von <code>DiagnosticPortInterface</code> (im Kontext von <code>PortInterface</code>) abgeleitet ist. Manifest-Modellierer und Generatoren leiten die Validierungsschnittstelle für Diagnosedienste aus der abstrakten Diagnose-Port-Schnittstelle ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f731038873571032", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm stellt die Generalisierungsbeziehung von <code>DiagnosticServiceValidationInterface</code> zu <code>DiagnosticPortInterface</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Klassenblöcke:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticPortInterface</code> (oberer Klassenblock, Klassenname kursiv) mit dem rechtsbündig gesetzten kursiven Stereotyp bzw. Kontextvermerk <code>PortInterface</code>.\n</li><li><code>DiagnosticServiceValidationInterface</code> (unterer Klassenblock), spezialisiert <code>DiagnosticPortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierungsbeziehung).\n</li></ul>\n<p class=\"fig-p\">Attribute oder Methoden sind in den Klassenblöcken nicht aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ fest, dass <code>DiagnosticServiceValidationInterface</code> von <code>DiagnosticPortInterface</code> (im Kontext von <code>PortInterface</code>) abgeleitet ist. Manifest-Modellierer und Generatoren leiten die Validierungsschnittstelle für Diagnosedienste aus der abstrakten Diagnose-Port-Schnittstelle ab.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b94459ab7c95c9c", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation innerhalb der AUTOSAR Adaptive Platform (Manifest Specification). Das Diagramm stellt die Generalisierungsbeziehung von <code>DiagnosticServiceValidationInterface</code> zu <code>DiagnosticPortInterface</code> dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei Klassenblöcke:</p>\n<ul class=\"fig-list\"><li><code>DiagnosticPortInterface</code> (oberer Klassenblock, Klassenname kursiv) mit dem rechtsbündig gesetzten kursiven Stereotyp bzw. Kontextvermerk <code>PortInterface</code>.\n</li><li><code>DiagnosticServiceValidationInterface</code> (unterer Klassenblock), spezialisiert <code>DiagnosticPortInterface</code> über eine geschlossene, nicht ausgefüllte Pfeilspitze (Generalisierungsbeziehung).\n</li></ul>\n<p class=\"fig-p\">Attribute oder Methoden sind in den Klassenblöcken nicht aufgeführt.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm der Metamodell-Klassifikation ohne dynamisches Laufzeit- oder Sequenzverhalten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt normativ fest, dass <code>DiagnosticServiceValidationInterface</code> von <code>DiagnosticPortInterface</code> (im Kontext von <code>PortInterface</code>) abgeleitet ist. Manifest-Modellierer und Generatoren leiten die Validierungsschnittstelle für Diagnosedienste aus der abstrakten Diagnose-Port-Schnittstelle ab.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-d2284518ead111ad", "to": "FIG-30f45b2cab2aaff4", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-30f45b2cab2aaff4", "to": "FIG-00e7b49fe6fe9e78", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Basisklasse <code>PortInterface</code> (mit den Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>) als separater Klassenkasten entfällt; stattdessen ist <code>PortInterface</code> nun als kursiver Stereotyp bzw. Kontextannotation oberhalb des Klassennamens <code>DiagnosticPortInterface</code> aufgeführt.\n</li><li>Die explizite Generalisierungsbeziehung (Vererbungspfeil) von <code>DiagnosticPortInterface</code> zu <code>PortInterface</code> entfällt im Diagramm.\n</li></ul>"}, {"from": "FIG-00e7b49fe6fe9e78", "to": "FIG-74d3e8457a658547", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-74d3e8457a658547", "to": "FIG-6bc4ed2660cf340b", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6bc4ed2660cf340b", "to": "FIG-f731038873571032", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f731038873571032", "to": "FIG-9b94459ab7c95c9c", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
